function createUsageTracker(limit) {
  let used = 0;                       // private: only the inner functions can see it
  return {
    add(tokens) {
      if (used + tokens > limit) return false;
      used += tokens;
      return true;
    },
    remaining: () => limit - used,
  };
}

const tracker = createUsageTracker(1000);
tracker.add(400);
tracker.add(700);                     // rejected: would exceed the limit
console.log(tracker.remaining());     // 600
console.log(tracker.used);            // undefined

const messages = [
  { role: 'user', tokens: 12 },
  { role: 'assistant', tokens: 140 },
  { role: 'user', tokens: 9 },
];
const totals = messages.reduce((acc, { role, tokens }) => {
  acc[role] = (acc[role] ?? 0) + tokens;
  return acc;
}, {});
console.log(totals);
console.log(messages.length);

