const rows = stdin.split('\n').map((l) => l.trim()).filter(Boolean);

const parsed = rows.map((line) => {
  const [name = '', course = '', raw = ''] = line.split(',').map((s) => s.trim());
  const score = raw === '' ? NaN : Number(raw);
  return { name, course, score };
});

const isValid = ({ name, course, score }) =>
  name !== '' && course !== '' && Number.isFinite(score) && score >= 0 && score <= 100;
const valid = parsed.filter(isValid);

const byCourse = valid.reduce((acc, r) => {
  (acc[r.course] = acc[r.course] || []).push(r);
  return acc;
}, {});

const courses = Object.keys(byCourse).sort();
if (courses.length === 0) console.log('No valid records');
for (const course of courses) {
  const list = byCourse[course];
  const avg = list.reduce((sum, r) => sum + r.score, 0) / list.length;
  const top = [...list].sort((a, b) => b.score - a.score || (a.name < b.name ? -1 : 1))[0];
  console.log(`${course}: avg=${avg.toFixed(1)} top=${top.name} (${top.score}) count=${list.length}`);
}
console.log(`Skipped: ${parsed.length - valid.length}`);

